use crate::aap::caps::{http_client, state_rw};

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encodes everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(hex_digit(b >> 4));
                out.push(hex_digit(b & 0x0f));
            }
        }
    }
    out
}

fn hex_digit(n: u8) -> char {
    b"0123456789ABCDEF"[n as usize] as char
}

/// PublishedDigest has no free-text field, so the enrichment query is built
/// from its date and the considered item ids. Assumption: this is the
/// "input's text" for the enrichment lookup.
fn enrichment_text(published: &PublishedDigest) -> String {
    let mut text = published.date.clone();
    for id in &published.considered {
        text.push(',');
        text.push_str(id);
    }
    text
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment lookup, approved for this node. Its result is deliberately
        // discarded (and a transport failure is a value, not a trap), so the
        // node's output does not depend on it.
        let url = format!(
            "{}{}",
            ENRICH_BASE,
            percent_encode(&enrichment_text(&published))
        );
        let _ = http_client::fetch(&url);

        // Mark every considered item as seen. Assumption: when the digest was
        // not published, nothing is marked seen, so those items are retried on
        // the next run.
        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
